"""Shared probe helpers for the checkout_total negative-quantity contract.

The contract (README.md) states: checkout_total must reject negative quantity
with ValueError. The probe therefore calls checkout_total with a negative
quantity and reports whether the omission (no validation) is observable.
"""

import types

SOURCE_PATH = "/source/sample.py"


def read_source(path=SOURCE_PATH):
    with open(path, "r", encoding="utf-8") as handle:
        return handle.read()


def load_module(name, source_text):
    module = types.ModuleType(name)
    module.__dict__["__file__"] = name
    exec(compile(source_text, name, "exec"), module.__dict__)
    return module


def evaluate(module):
    """Return (claim_present, detail).

    claim_present is True when checkout_total accepts a negative quantity and
    returns a product instead of raising ValueError.
    """
    fn = getattr(module, "checkout_total", None)
    if fn is None:
        return False, {"outcome": "missing_function"}
    try:
        value = fn(250, -3)
    except ValueError as exc:
        return False, {"outcome": "raised_ValueError", "message": str(exc)}
    except Exception as exc:  # noqa: BLE001 - any other error is not the contract
        return False, {
            "outcome": "raised_other",
            "exception_type": type(exc).__name__,
            "message": str(exc),
        }
    return True, {"outcome": "returned_value", "value": value}

